"""Build a local, source-linked side-by-side review from real recorded results."""
from pathlib import Path
import html,json

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'artifacts/ocr-stage1'
DATA=OUT/'dataset'

def load_rows(path):
    rows={}
    if path.exists():
        for line in path.read_text(encoding='utf-8').splitlines():
            r=json.loads(line);rows[r['id']]=r
    return rows

def main():
    manifest=json.loads((DATA/'samples.json').read_text(encoding='utf-8'))
    metrics=json.loads((OUT/'results/metrics.json').read_text(encoding='utf-8'))
    paths={'rapidocr':OUT/'results/rapidocr/rapidocr.jsonl','minicpm':OUT/'results/minicpm/results.jsonl','paddle':OUT/'results/paddle/results.jsonl'}
    rows={k:load_rows(p)for k,p in paths.items()};samples=[]
    for s in manifest['samples']:
        x=dict(s);x['image_url']='dataset/'+s['image_relpath']
        x['reference']=(DATA/s['native_text_relpath']).read_text(encoding='utf-8')if s.get('native_text_relpath')else None
        x['outputs']={k:v.get(s['id'])for k,v in rows.items()}
        samples.append(x)
    audit=json.loads((OUT/'visual-review.json').read_text(encoding='utf-8'))
    data=json.dumps({'samples':samples,'metrics':metrics,'audit':audit},ensure_ascii=False).replace('<','\\u003c')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AIcademiya · Document parsing evaluation</title>
<style>
:root{color-scheme:light;font-family:system-ui,Arial,sans-serif;color:#21352d;background:#f5f5ef}*{box-sizing:border-box}body{margin:0}header{padding:24px 32px;background:#31584b;color:white}h1{margin:0 0 6px;font:600 26px Georgia,serif}header p{margin:0;opacity:.88;font-size:14px}main{padding:22px;max-width:1700px;margin:auto}.notice{padding:12px 16px;border-left:4px solid #9b7938;background:#fff7e3;font-size:14px;line-height:1.6}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.card{padding:16px;border:1px solid #d9ded6;border-radius:10px;background:white}.card h2{font-size:16px;margin:0 0 10px}.card p{margin:5px 0;font-size:14px}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:18px 0}select,button{font:inherit;padding:8px 12px;border:1px solid #bcc7bd;border-radius:6px;background:white;color:inherit}select{max-width:100%}button{cursor:pointer}button:hover,button.active{background:#31584b;color:white}.work{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px}.panel{min-width:0;background:white;border:1px solid #d9ded6;border-radius:10px;padding:16px}.panel h2{font-size:17px;margin:0 0 8px}.image-wrap{max-height:850px;overflow:auto;background:#e9ece6;text-align:center;border-radius:6px}.image-wrap img{display:block;width:100%;height:auto;margin:auto}.meta{font-size:13px;line-height:1.6;overflow-wrap:anywhere;color:#59675f}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 ui-monospace,Consolas,monospace;max-height:730px;overflow:auto;background:#f7f8f4;padding:14px;border-radius:6px}details{margin-top:18px}summary{cursor:pointer;font-weight:600}.metric{padding:10px;background:#f0f5ef;font-size:13px;line-height:1.6}.reading{white-space:pre-wrap;line-height:1.6;max-height:730px;overflow:auto;padding:12px;background:#f7f8f4;border-radius:6px}.reading table{white-space:normal;border-collapse:collapse;font-size:13px;max-width:100%}.reading td,.reading th{border:1px solid #b6c6b6;padding:7px;vertical-align:top}.status{font-size:12px;border-radius:20px;padding:3px 9px;background:#e5efe6}.footer{font-size:13px;line-height:1.7;color:#59675f;margin:24px 0}a{color:#245b77}@media(max-width:820px){header{padding:20px}main{padding:12px}.work,.summary{grid-template-columns:1fr}.image-wrap{max-height:550px}h1{font-size:23px}}
</style><header><h1>AIcademiya · Document parsing evaluation</h1><p>Phase 1 · Actual Ubuntu runs · 24 source-linked image samples · No production deployment</p></header><main>
<div class="notice">A returned transcription is not proof of accuracy. Reference metrics compare against native PDF / Office-export text, which may omit image text or have a different reading order. Three samples have no reliable native reference. AI visual review is separate from these diagnostics; no human-gold accuracy or combined score is claimed.</div>
<div id="summary" class="summary"></div><div class="toolbar"><label for="sample">Sample</label><select id="sample"></select><button id="prev">Previous</button><button id="next">Next</button><button id="zoom">Source: fit / 200%</button></div>
<div class="work"><section class="panel"><h2>Original rendered page</h2><p id="sourceMeta" class="meta"></p><div class="image-wrap"><img id="sourceImage" alt="Selected original course page"></div><p><a id="fullImage" target="_blank">Open full-resolution image</a></p></section>
<section class="panel"><h2>Recorded output</h2><div class="tabs" id="tabs"></div><button id="readable">Readable / raw output</button><div id="runMeta" class="meta"></div><div id="caseMetrics" class="metric"></div><p id="observations" class="meta"></p><div id="reading" class="reading"></div><pre id="output"></pre></section></div>
<details><summary>Native text reference — not human gold</summary><p id="refKind" class="meta"></p><pre id="reference"></pre></details>
<div class="footer">Quantized MiniCPM-V 4.5 and official PaddleOCR-VL 1.6 GGUF were run on the same Ubuntu T10. Paddle includes CPU layout detection; RapidOCR uses the original CPU model files. Initialization, image processing, whole-file extraction limits and quality are distinct measurements.<br>See the Chinese final report and PIPELINE_PROPOSAL.md alongside this file. Original source files were not modified.</div></main><script id="data" type="application/json">DATA_PLACEHOLDER</script>
<script>
const data=JSON.parse(document.querySelector('#data').textContent), names={rapidocr:'Current CPU OCR',minicpm:'MiniCPM-V 4.5 · Q4_K_M',paddle:'PaddleOCR-VL 1.6 · full pipeline'};
let index=0,engine='minicpm',zoom=false,readable=true;
const $=s=>document.querySelector(s),fmt=(x,n=2)=>x==null?'Not available':Number(x).toFixed(n),pct=x=>x==null?'Not scored':fmt(x*100,1)+'%';
for(const [key,name]of Object.entries(names)){const m=data.metrics.summary[key],card=document.createElement('section');card.className='card';const h=document.createElement('h2');h.textContent=name;card.append(h);for(const text of [`Recorded ${m.records} / ${m.expected} samples`,`Nonempty outputs: ${m.status_counts.ok||0} (not accuracy)`,`Median image time: ${fmt(m.median_image_elapsed_seconds)} s`,`Reference comparison cases: ${m.reference_scored_cases}`,`Peak total GPU memory: ${m.gpu_peak_used_mib==null?'CPU / not sampled':m.gpu_peak_used_mib+' MiB'}`]){const p=document.createElement('p');p.textContent=text;card.append(p)}$('#summary').append(card);const b=document.createElement('button');b.textContent=name;b.dataset.engine=key;b.onclick=()=>{engine=key;render()};$('#tabs').append(b)}
data.samples.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${s.id} · ${s.source_id} · page/slide ${s.page_1based} · ${s.category}`;$('#sample').append(o)});
function safeReading(text){const t=document.createElement('template');t.innerHTML=text;const allowed=new Set(['TABLE','THEAD','TBODY','TR','TD','TH','P','DIV','SPAN','BR','UL','OL','LI','STRONG','EM','B','I','SUB','SUP']);function copy(n){if(n.nodeType===3)return document.createTextNode(n.textContent);if(n.nodeType!==1)return document.createDocumentFragment();if(['SCRIPT','STYLE','IFRAME','OBJECT'].includes(n.tagName))return document.createDocumentFragment();if(n.tagName==='IMG')return document.createTextNode('[Image region — inspect the original page]');const out=allowed.has(n.tagName)?document.createElement(n.tagName.toLowerCase()):document.createDocumentFragment();if(['TD','TH'].includes(n.tagName))for(const a of ['colspan','rowspan']){const v=Number(n.getAttribute(a));if(v>=1&&v<=30)out.setAttribute(a,v)}for(const child of n.childNodes)out.append(copy(child));return out}const f=document.createDocumentFragment();for(const child of t.content.childNodes)f.append(copy(child));return f}
function render(){const s=data.samples[index],r=s.outputs[engine],m=data.metrics.cases.find(c=>c.id===s.id).models[engine];$('#sample').value=index;$('#sourceImage').src=s.image_url;$('#sourceImage').style.width=zoom?'200%':'100%';$('#fullImage').href=s.image_url;$('#sourceMeta').textContent=s.source_path+' · '+s.unit_kind+' '+s.page_1based+' / '+s.selection_reason;$('#output').textContent=r?(r.text||r.error||'No text returned'):'No recorded result';$('#runMeta').textContent=r?`Status: ${r.status} · ${fmt(r.elapsed_seconds)} s · ${r.gpu_peak_used_mib||'CPU / unknown'} MiB · finish: ${r.finish_reason||'not exposed by pipeline'}`:'Missing';const issue=data.audit.unreliable_native_reference_ids[s.id];$('#caseMetrics').textContent=issue?`Reference warning: ${issue}. No accuracy score shown.`:'Automatic native-reference diagnostics are retained in results/metrics.json, not treated as an OCR quality score. Compare the original page and transcript.';$('#reading').replaceChildren(safeReading(r?(r.text||r.error||'No text returned'):'No recorded result'));$('#reading').hidden=!readable;$('#output').hidden=readable;const note=data.audit.notes[s.id]?.observations;$('#observations').textContent=note?('AI visual spot-check (not human gold): '+(note[engine]||note.all||note.reference||'')):'';$('#refKind').textContent=s.reference_kind;$('#reference').textContent=s.reference||'No reliable native text reference. Inspect the original image and recorded outputs.';document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('active',b.dataset.engine===engine));$('#prev').disabled=index===0;$('#next').disabled=index===data.samples.length-1}
$('#readable').onclick=()=>{readable=!readable;render()};$('#sample').onchange=e=>{index=Number(e.target.value);render()};$('#prev').onclick=()=>{index--;render()};$('#next').onclick=()=>{index++;render()};$('#zoom').onclick=()=>{zoom=!zoom;render()};render();
</script></html>'''.replace('DATA_PLACEHOLDER',data)
    target=OUT/'review.html';target.write_text(page,encoding='utf-8')
    print(json.dumps({'review':str(target),'samples':len(samples),'bytes':target.stat().st_size}))

if __name__=='__main__':main()
